  const euros = cents / 100;
  const formatted = Math.abs(euros).toLocaleString('en-US', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
  return (cents < 0 ? '-' : '') + '€' + formatted;
}

